float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }
float lum(vec3 x) { return dot(x, vec3(0.32, 0.49, 0.29)); }
float lum(vec4 x) { return dot(x.rgb, vec3(0.32, 0.49, 0.29)); }
float sat(float x) { return clamp(x, 0.0, 1.0); }
vec2 sat(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 sat(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 sat(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_clouds sampler_noise_lq
#define sampler_pw_noise_lq sampler_noise_lq
sampler sampler_clouds;
sampler sampler_pw_noise_lq;
vec3 noise, noise1, bfly, neu, bush;
vec2 rs, uv1, dz, uvo;
float k, z0, z, dk, hinten;
int n;
//Wolken
vec2 uv4 = uv1;
float z4 = clamp(1.0 / (abs(uv4.y-.1)),-0, 18.0 );
rs = vec2(uv4.x * z4, z4 * 2.0+uTime) / 12.0 ;
vec3 clouds = lum(texture(sampler_noise_hq,rs+.0*uTime));
clouds *= clamp01(1.0 - uv.y) ;
clouds *= vec3 (.4,.7, 1.0 - uv4.y)*.5;
//Buschwerk
bush = 0;
for (n=0; n<=1; n++) {
vec2 uv5 = uv1+vec2 ( 0.0 ,-n*.04);
uv5.x += (uv.y*1.05* (q19*(n%2) + q20*((n + 1.0)%2)));
neu = abs(uv5.y)
*(1.0 + texture(sampler_noise_lq,vec2(uv5.x * 2.0,uv5.y * 4.0)).g)
*(3+2*texture(sampler_noise_hq,uv5.x / 2.0*(1.0 + n%2)).g);
neu = clamp01(.2*neu-.4) * clamp01(-8*uv5.y);
float red = .5+.5*texture(sampler_noise_hq,uv5 * 2.0);
float vis = clamp01(4.0 * texture(sampler_noise_hq,uv5 * 8.0)
*texture(sampler_noise_hq,uv5 * 24.0));
neu *= vec3 (2.0 * red, 1.0 ,.2) *vis ;
bush = max(bush,neu);
}
vec3 scene = clamp01(clouds*(1-32*bush)) + bush;
ret = scene*clamp01(1-8*bfly)+bfly;
//ret = bfly * 2.0;
//ret = GetPixel (uvo) * 2.0;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uvo = uv_orig;
uv1 = uv-vec2 (.5, 1.0 );
uv1 *= uAspect.xy;
hinten = 1.0 / (uv1.y-0.1);//sqrt nur Verringerung Rechenzeit
hinten = clamp(hinten,-6, 0.0 );
bfly = 0;
float trel = uTime; ;
for (n=1; n <= 2; n++)
{  k = 0;
z0 = n*1.5;
rs.x = (uv1.x)*z0*hinten + n / 4.0;//Zentrum x
rs.y = z0*hinten-trel;
//noise1 ist Maske fuer Desync der Fluegelschlaege
//Problem: k erst nachher bekannt, deshalb muss
//Amplitude oder Groesse begrenzt werden
noise1 = texture(sampler_pw_noise_lq,rs / 256.0);
k += .4*sin(uTime * 16.0* (.5+noise1.r)); //Fluegelschlag
z = k*abs((fract(rs.x))-.5)+ z0;
//  z -= .5*clamp01(.05-pow(sin(6.3*(rs.x)), 2.0 )); //Rumpfform
z -= .04*k; //Koerperbewegung
rs.y = z*hinten-trel;
rs = fract(rs.yx) ;
neu = GetBlur1(rs) - (1.0 - q18 * 16.0)*GetBlur2(rs);
neu *= normalize(noise1) * 8.0*clamp01(6.0 + hinten)/hinten;
bfly += abs(neu) * (lum(noise1) >= .86) * (hinten <= 0);
  fragColor = vec4(ret, 1.0);
}

